mapper.select:
select clue.*, user.name as assignName
from clue
         left join user on clue.user_id = user.id


        clue.id = #{clueDto.clueId}


        and clue.phone like concat('%', #{clueDto.phone}, '%')


        and clue.status = #{clueDto.status}


        and clue.channel = #{clueDto.channel}


        and clue.name like concat('%', #{clueDto.assignName}, '%')



        and clue.user_id = #{clueDto.scopeUserId}

select clue.*, activity.name as activityName
from clue
         left join activity on clue.activity_id = activity.id


        clue.id = #{clueDto.clueId}


        and clue.phone like concat('%', #{clueDto.phone}, '%')


        and clue.channel = #{clueDto.channel}
